"""Chapter 14 Practical Electricity: written-answer questions, 5 per level."""
from .. import sketches2 as sk
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall

# ---------------------------------------------------------------- L1
written("w14_heating_effect_use", 14, 1, "14a",
        stem="Fig. 1 shows the rating plate of a kettle. Name the effect of an electric current that a kettle uses, and name one other appliance that uses the same effect.",
        points=[P("the heating effect of a current; e.g. an electric oven, heater, iron, toaster or hair dryer", ["heating effect", "heating", "heat", "thermal effect"]),
                P("another appliance", ["oven", "heater", "iron", "toaster", "hair dryer", "hairdryer", "water heater", "cooker", "hob"])],
        model_answer="A kettle uses the heating effect of an electric current: the current in the element transfers energy to it and raises its temperature. Other appliances using the same effect include electric ovens, heaters, irons and toasters.",
        hints=["What does the current do to the kettle's element?",
               "Think of other appliances whose job is to get hot.",
               "Name the effect and one more appliance."],
        keywords="heating effect; oven / heater / iron / toaster",
        figure=lambda: sk.rating_plate(["230 V", "2000 W"], title="kettle"),
        sample_pass=["The heating effect; an electric oven also uses it", "heating effect of a current, also used in a toaster"],
        sample_fail=["The magnetic effect; a motor", "The lighting effect; a lamp"])

written("w14_live_neutral_earth", 14, 1, "14g",
        stem="Fig. 1 shows the inside of a three-pin plug. State the meaning of the terms live, neutral and earth.",
        points=[P("live: the wire at high (alternating) potential that carries the current to the appliance (brown)", ["live carries the current", "live is at high", "live wire carries", "high potential", "high voltage", "brown", "live delivers", "live supplies", "live is the wire that"]),
                P("neutral: the return wire at or near 0 V, completing the circuit (blue)", ["neutral completes", "completes the circuit", "return wire", "return path", "near zero", "near 0", "0 v", "zero volts", "blue", "neutral is at 0", "neutral at zero", "neutral is at about 0"]),
                P("earth: a safety wire connected to the metal casing and to the ground, normally carrying no current (green/yellow)", ["safety wire", "safety", "metal casing", "connected to the ground", "connects the casing", "casing to the ground", "green", "yellow", "normally carries no current", "no current normally", "carries current only"])],
        min_points=2,
        pitfalls=[PF(["live is positive", "neutral is negative", "live is the positive", "neutral is the negative"], "Mains electricity is a.c.: the live wire is at a high ALTERNATING potential and the neutral is near 0 V; they are not + and −.")],
        model_answer="The live wire (brown) is at a high alternating potential and carries current from the supply to the appliance. The neutral wire (blue) completes the circuit and is at or near 0 V. The earth wire (green/yellow) is a safety wire connected to the metal casing of the appliance and to the ground; it normally carries no current.",
        hints=["One wire brings the current in, one takes it back, and one is only for safety.",
               "Think about the potential of each and what it is connected to.",
               "Give the meaning of each of the three terms."],
        keywords="live: high potential, carries current; neutral: return, ~0 V; earth: safety, casing to ground",
        figure=lambda: sk.plug_sketch(),
        sample_pass=["Live carries the current at high potential, neutral is the return at about 0 V, and earth connects the metal casing to the ground for safety",
                     "the brown live wire is at high voltage, the blue neutral completes the circuit, the green and yellow earth is a safety wire that normally carries no current"],
        sample_fail=["Live is positive, neutral is negative, earth is the ground you stand on", "They are the three pins"])

written("w14_fuse_purpose", 14, 1, "14e",
        stem="State the purpose of a fuse in an electrical circuit.",
        points=[P("it melts (breaks the circuit) if the current becomes too large, protecting the appliance and wiring from overheating / fire", ["melts", "breaks the circuit", "cuts off", "too large", "too big", "too high", "excess current", "protect", "overheat", "fire"])],
        pitfalls=[PF(["protects the person", "protects the user", "stops electric shock", "prevent shock"], "A fuse protects the wiring and appliance from large currents; it does not act fast enough to protect a person from shock.")],
        model_answer="A fuse is a thin wire that melts and breaks the circuit if the current becomes too large, protecting the appliance and the wiring from overheating and fire.",
        hints=["A fuse is a deliberately weak link. What makes it fail, and what does that achieve?",
               "It responds to too much current.",
               "State what it does and what it protects."],
        keywords="melts if current too large, breaks circuit, protects wiring/appliance from overheating",
        sample_pass=["It melts and breaks the circuit if the current gets too big, protecting the wiring from overheating", "a thin wire that cuts off the current when it is too large to prevent fire"],
        sample_fail=["It stops people getting electric shocks", "It makes the current flow more smoothly"])

written("w14_hazards_three", 14, 1, "14d",
        stem="State the hazard presented by each of the following: damaged insulation, overheating of cables, and using electrical equipment in damp conditions.",
        points=[P("damaged insulation: exposed live wires can cause electric shock (or a short circuit)", ["exposed", "bare wire", "touch the live", "electric shock", "shock", "short circuit"]),
                P("overheating cables: too large a current heats the cable, which can melt insulation and start a fire", ["fire", "melt", "catch fire", "burn", "overheat"]),
                P("damp conditions: water conducts, lowering resistance and giving a path for current through the body, causing shock / electrocution", ["water conducts", "lowers resistance", "reduces resistance", "path through the body", "electrocut", "conducts electricity", "damp skin"])],
        min_points=2,
        model_answer="Damaged insulation can expose live wires, so a person touching them receives an electric shock, and touching wires may cause a short circuit. Overheating cables, caused by too large a current, can melt the insulation and start a fire. In damp conditions water conducts electricity and lowers the resistance of the skin, so current can flow through the body and cause a severe shock.",
        hints=["Each situation leads to a different danger: shock, fire, or shock again. Match them.",
               "Think about what bare wires, hot cables and wet hands each allow current to do.",
               "State the hazard for each situation."],
        keywords="damaged insulation → shock/short; overheating → fire; damp → water conducts, shock",
        sample_pass=["Damaged insulation exposes live wires and can give a shock; overheating cables can start a fire; damp conditions let water conduct and cause electrocution",
                     "bare wires cause electric shock, hot cables melt and catch fire, and wet hands lower resistance so current flows through you"],
        sample_fail=["They all make the electricity bill higher", "The appliance stops working"])

written("w14_unit_kwh", 14, 1, "14c",
        stem="State what is meant by one kilowatt-hour (kWh).",
        points=[P("the energy transferred by a 1 kW appliance in 1 hour (= 3 600 000 J)", ["1 kw for 1 hour", "1 kw in 1 hour", "one kilowatt for one hour", "1000 w for 1 hour", "kilowatt running for an hour", "1 kw appliance in one hour", "3 600 000", "3.6 million", "3.6 × 10"])],
        pitfalls=[PF(["unit of power", "measures power", "is a power"], "The kWh is a unit of ENERGY, not power: it is power (kW) multiplied by time (h).")],
        model_answer="One kilowatt-hour is the energy transferred by a 1 kW appliance running for 1 hour; it equals 1000 W × 3600 s = 3 600 000 J.",
        hints=["Look at the name: a power unit multiplied by a time unit. What does power × time give?",
               "It is the energy used by a 1 kW device in 1 hour.",
               "Write the definition as a sentence."],
        keywords="energy of 1 kW for 1 hour (3.6 MJ)",
        sample_pass=["The energy used by a 1 kW appliance in one hour", "1000 W for 1 hour, which is 3 600 000 J"],
        sample_fail=["A unit of power", "The power used by an appliance in one hour"])

# ---------------------------------------------------------------- L2
written("w14_fuse_rating_choice", 14, 2, "14e",
        stem="Fig. 1 shows the rating plate of an appliance: 920 W, 230 V. Explain how you would choose a suitable fuse from 3 A, 5 A and 13 A.",
        points=[P("find the normal current: I = P ÷ V = 920 ÷ 230 = 4 A", ["920 ÷ 230", "920 / 230", "4 a", "i = p", "p ÷ v", "p / v", "power divided by"]),
                P("choose the smallest fuse rated just above the normal current: 5 A", ["5 a", "just above", "slightly above", "next above", "smallest fuse above", "a little higher than"]),
                P("a 3 A fuse would blow in normal use; a 13 A fuse would allow a dangerously large current before blowing", ["3 a would blow", "would blow in normal use", "too low", "13 a would allow", "too high", "would not protect", "not blow soon enough"])],
        min_points=2,
        model_answer="First work out the normal operating current: I = P ÷ V = 920 ÷ 230 = 4 A. The fuse should be the smallest available rating just above this, so 5 A. A 3 A fuse would blow during normal use, while a 13 A fuse would allow a current far above normal to flow before it blew, so it would not protect the appliance properly.",
        hints=["The fuse must not blow at the normal current, but should blow soon above it. So you need the normal current first.",
               "I = P ÷ V. Then pick the next rating up.",
               "Show the calculation and justify the choice."],
        keywords="I = P/V = 4 A; choose 5 A (smallest above normal current)",
        figure=lambda: sk.rating_plate(["920 W", "230 V"]),
        sample_pass=["I = 920/230 = 4 A, so choose the 5 A fuse, the smallest rating above the normal current", "the current is 4 A; a 3 A fuse would blow normally and 13 A is too high, so use 5 A"],
        sample_fail=["Choose 13 A so it never blows", "Choose 3 A because it is the safest"])

written("w14_earthing_metal_casing", 14, 2, "14f",
        stem="Explain why appliances with a metal casing must have the casing connected to the earth wire.",
        points=[P("if a fault makes the live wire touch the casing, the casing would become live and could give a shock", ["live wire touches the casing", "casing becomes live", "fault", "touches the metal case", "would become live", "casing live"]),
                P("the earth wire provides a low-resistance path from the casing to the ground, so a large current flows", ["low resistance path", "low-resistance path", "path to the ground", "path to earth", "large current flows", "current flows to earth", "easy path"]),
                P("this large current blows the fuse, cutting off the supply and making the appliance safe", ["blows the fuse", "fuse blows", "fuse melts", "cuts off", "breaks the circuit", "disconnects"])],
        min_points=2,
        model_answer="If a fault allows the live wire to touch the metal casing, the casing becomes live and anyone touching it could get a shock. The earth wire connects the casing to the ground through a low-resistance path, so a large current flows to earth as soon as the fault occurs. This large current blows the fuse and cuts off the supply, making the appliance safe.",
        hints=["What is the danger if a live wire inside the appliance comes loose and touches the case?",
               "What does an earth wire do with that current, and what does the large current then do to the fuse?",
               "Explain the fault, the earth path, and the fuse."],
        keywords="fault makes casing live; earth gives low-resistance path, large current; fuse blows",
        figure=lambda: sk.plug_sketch(),
        sample_pass=["If the live wire touches the casing it becomes live; the earth wire gives a low-resistance path so a large current flows and blows the fuse",
                     "earthing means a fault current goes to the ground instead of through a person, and the big current melts the fuse"],
        sample_fail=["The earth wire makes the appliance work better", "So that the casing does not rust"])

written("w14_double_insulation", 14, 2, "14f",
        stem="Some appliances, such as hair dryers, have no earth wire but are 'double insulated'. Explain what this means and why no earth is needed.",
        points=[P("the casing is made of an insulator (plastic) and the live parts inside are also insulated, so there are two layers of insulation", ["plastic casing", "insulating casing", "two layers", "casing is an insulator", "double layer", "non-conducting case", "internal parts are insulated"]),
                P("so even if an internal wire comes loose, the casing cannot become live and cannot give a shock", ["cannot become live", "cannot go live", "casing cannot", "no metal part can go live", "no part can become live", "no metal parts to touch", "cannot give a shock", "no shock", "cannot conduct to the user"]),
                P("therefore no earth connection is needed (the plug has only live and neutral)", ["no earth is needed", "does not need an earth", "earth not required", "nothing to earth", "no need for an earth", "no need to earth", "only live and neutral", "two-core"])],
        min_points=2,
        model_answer="A double-insulated appliance has a casing made of an insulating material such as plastic, and its live parts inside are also insulated, giving two layers of insulation between the live wires and the user. Even if a wire comes loose inside, the casing cannot become live, so there is no shock risk from touching it and no earth wire is needed.",
        hints=["What is the casing made of, and how many layers of insulation are there between the live wire and your hand?",
               "An earth wire protects you when a METAL casing goes live. Can a plastic casing go live?",
               "Explain the two layers and why earthing is unnecessary."],
        keywords="plastic insulating casing + insulated internals; casing cannot become live; no earth needed",
        sample_pass=["The casing is plastic and the inside parts are insulated too, so the case can never become live and no earth wire is needed",
                     "two layers of insulation mean no metal part can go live, so there is nothing to earth"],
        sample_fail=["It has two earth wires for extra safety", "The insulation is twice as thick to keep heat in"])

written("w14_switch_live_wire", 14, 2, "14i",
        stem="Explain why the switch and the fuse of an appliance are fitted in the live wire rather than in the neutral wire.",
        points=[P("the live wire is at high potential; when the switch is off (or the fuse has blown) in the live wire, the appliance is disconnected from the high potential", ["disconnected from the live", "isolates the appliance", "no longer at high potential", "cuts off the live", "removes the high voltage", "appliance is isolated", "separates the appliance from the live"]),
                P("if they were in the neutral wire, the appliance would still be connected to the live supply even when switched off or when the fuse had blown", ["still connected to the live", "connected to the live supply", "leaves it connected", "still live", "would still be at high", "remain live", "still at mains potential", "live even when off"]),
                P("so someone touching a live part inside the switched-off appliance could still get a shock", ["still get a shock", "could get a shock", "shock", "dangerous even when switched off", "electrocut"])],
        min_points=2,
        model_answer="The live wire is the one at high potential. Putting the switch and fuse in the live wire means that when the switch is off or the fuse has blown, the appliance is disconnected from the high potential and is safe to handle. If they were in the neutral wire, the appliance would stay connected to the live supply even when switched off, so anyone touching a live part inside could still receive a shock.",
        hints=["Which wire is dangerous: live or neutral? Where must you break the circuit to remove that danger?",
               "Imagine the switch in the neutral wire and the appliance 'off'. Is the inside still live?",
               "Explain the isolation and the danger of the alternative."],
        keywords="live wire is at high potential; switch/fuse in live isolates appliance; in neutral it would stay live",
        figure=lambda: sk.plug_sketch(),
        sample_pass=["So that when the switch is off or the fuse blows the appliance is disconnected from the high-potential live wire; in the neutral it would still be live and could shock someone",
                     "breaking the live wire isolates the appliance; breaking the neutral leaves it connected to the live supply"],
        sample_fail=["Because the live wire is thicker", "So that the current flows faster"])

written("w14_plug_wiring", 14, 2, "14h",
        stem="Fig. 1 shows a three-pin plug. Describe how the three wires of a cable are connected inside the plug, including their colours.",
        points=[P("live (brown) to the right-hand pin, through the fuse", ["brown", "live to the right", "fuse", "live is brown"]),
                P("neutral (blue) to the left-hand pin", ["blue", "neutral to the left", "neutral is blue"]),
                P("earth (green/yellow) to the top (longer) pin; the cable grip holds the outer sheath", ["green", "yellow", "top pin", "longer pin", "cable grip", "earth to the top"])],
        min_points=2,
        model_answer="The live wire, coloured brown, connects to the right-hand pin through the fuse. The neutral wire, coloured blue, connects to the left-hand pin. The earth wire, coloured green and yellow, connects to the top (longer) pin. The cable grip clamps the outer sheath so that pulling the cable does not strain the connections.",
        hints=["Three wires, three pins, three colours. Which colour goes where?",
               "Live is brown and passes through the fuse; the earth pin is the top one.",
               "Describe all three connections with colours."],
        keywords="brown live → right pin via fuse; blue neutral → left pin; green/yellow earth → top pin",
        figure=lambda: sk.plug_sketch(labels=False),
        sample_pass=["Brown live to the right pin through the fuse, blue neutral to the left pin, green and yellow earth to the top pin", "the earth is green/yellow on the top pin, live brown on the fused pin, neutral blue on the other"],
        sample_fail=["Red to the top, black to the left, green to the right", "All three wires go to the fuse"])

# ---------------------------------------------------------------- L3
written("w14_why_fuse_blows", 14, 3, "14e",
        stem="Explain, in terms of the heating effect, how a fuse works and why its rating must be chosen carefully.",
        points=[P("the fuse contains a thin wire; current through it produces a heating effect, and a large enough current heats the wire until it melts", ["thin wire", "heating effect", "heats the wire", "melts", "gets hot enough"]),
                P("when the wire melts the circuit is broken and the current stops, protecting the appliance and cables", ["breaks the circuit", "circuit is broken", "current stops", "cuts off", "protect"]),
                P("the rating is the current at which it melts: it must be above the normal current (or it blows in normal use) but as low as possible so that a fault current blows it quickly", ["above the normal current", "normal current", "as low as possible", "just above", "blow in normal use", "fault current", "blows quickly", "too high a rating"])],
        min_points=2,
        model_answer="A fuse contains a thin piece of wire. Current through it has a heating effect, and if the current becomes large enough the wire heats up until it melts. The circuit is then broken and the current stops, protecting the appliance and the cables from overheating. The rating is the current at which the fuse melts: it must be a little above the normal current so the fuse does not blow in normal use, but as low as possible so that a fault current blows it quickly.",
        hints=["What is inside a fuse, and what does a current do to it?",
               "What happens to the circuit when the wire melts? Why would too low or too high a rating be a problem?",
               "Explain the melting, the broken circuit, and the choice of rating."],
        keywords="thin wire heats and melts at large current; circuit broken; rating just above normal current",
        sample_pass=["The thin wire heats up and melts if the current is too large, breaking the circuit; the rating must be just above the normal current so it does not blow normally but does blow with a fault",
                     "the heating effect melts the fuse wire at its rated current, cutting off the supply; too low and it blows in normal use, too high and it does not protect"],
        sample_fail=["The fuse absorbs the extra electricity", "A fuse works by cooling the wire down"])

written("w14_circuit_breaker_vs_fuse", 14, 3, "14e",
        stem="Explain how a circuit breaker protects a circuit, and give two advantages of a circuit breaker over a fuse.",
        points=[P("a circuit breaker is an automatic switch that opens (trips) when the current exceeds a set value, breaking the circuit", ["automatic switch", "trips", "opens when the current", "switches off when the current", "breaks the circuit", "cuts off"]),
                P("advantage: it can be reset by pressing a button or switch, rather than replaced", ["reset", "switched back on", "does not need replacing", "reused", "not replaced"]),
                P("advantage: it acts faster / more reliably than a fuse and cannot be fitted with the wrong rating", ["faster", "quicker", "more reliable", "more sensitive", "cannot be fitted with the wrong", "correct rating", "no need to find a fuse"])],
        min_points=2,
        model_answer="A circuit breaker is an automatic switch that trips open when the current exceeds a set value, breaking the circuit just as a blown fuse would. Unlike a fuse, it can simply be reset once the fault is cleared instead of being replaced, and it acts faster and more reliably; it also cannot be replaced with one of the wrong rating.",
        hints=["A circuit breaker does the same job as a fuse but in a different way. What kind of device is it?",
               "Think about what you have to do after a fuse blows, compared with after a breaker trips.",
               "Explain how it works and give two advantages."],
        keywords="automatic switch trips at set current; resettable; faster / no wrong rating",
        sample_pass=["It is an automatic switch that trips when the current is too high; it can be reset instead of replaced and it works faster than a fuse",
                     "a breaker cuts off the circuit at a set current and can be switched back on, and it is more reliable than a fuse"],
        sample_fail=["It is a fuse made of thicker wire", "It stores the extra current for later"])

